// smoke.spec.js — tool-specific checks for Audio Volume Booster and Normalizer.
// Fixtures are generated by tests/make-fixtures.mjs (fictional tone bursts, no real recordings).
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const dbOf = async (locator) => Number(await locator.getAttribute('data-db'));

async function load(page, name = 'quiet-sample.wav') {
  await page.goto('./');
  await page.setInputFiles('#file-input', fixture(name));
  await expect(page.locator('#editor')).toBeVisible();
}

async function saveAndWait(page) {
  await page.click('#save');
  await expect(page.locator('#out-peak')).toBeVisible({ timeout: 30_000 });
}

test.describe('Audio Volume Booster and Normalizer', () => {
  test('loading quiet-sample.wav shows peak and loudness in decibels', async ({ page }) => {
    await load(page);
    await expect(page.locator('#stat-peak')).toHaveText(/^−2[34]\.\d dBFS$/);
    await expect(page.locator('#stat-rms')).toHaveText(/^−\d+\.\d dB$/);
    await expect(page.locator('#stat-duration')).toHaveText('0:03.0');
    await expect(page.locator('#file-info')).toContainText('Stereo · 22,050 Hz');
    const peak = await dbOf(page.locator('#stat-peak'));
    expect(peak).toBeGreaterThan(-24.2);
    expect(peak).toBeLessThan(-23.8);
    expect(await dbOf(page.locator('#stat-rms'))).toBeLessThan(peak);
  });

  test('Boost by 6 dB raises the measured output peak by about 6 dB', async ({ page }) => {
    await load(page);
    await expect(page.locator('#gain-out')).toHaveText('+6.0 dB');
    await page.selectOption('#format', 'wav');
    const inPeak = await dbOf(page.locator('#stat-peak'));
    const inRms = await dbOf(page.locator('#stat-rms'));
    await expect(page.locator('#predict')).toContainText(/Predicted peak: −1[78]\.\d dBFS/);
    await saveAndWait(page);
    const outPeak = await dbOf(page.locator('#out-peak'));
    const outRms = await dbOf(page.locator('#out-rms'));
    expect(Math.abs(outPeak - inPeak - 6)).toBeLessThan(0.1);
    expect(Math.abs(outRms - inRms - 6)).toBeLessThan(0.1);
  });

  test('a huge boost clips at 0 dB, or is limited below 0 dB with Prevent clipping', async ({ page }) => {
    await load(page);
    await page.locator('#gain').fill('30');
    await expect(page.locator('#predict')).toContainText('Clipping warning');
    await page.selectOption('#format', 'wav');
    await saveAndWait(page);
    const clamped = await dbOf(page.locator('#out-peak'));
    expect(clamped).toBeLessThanOrEqual(0);
    expect(clamped).toBeGreaterThan(-0.01);

    await page.check('#limit');
    await expect(page.locator('#predict')).toContainText('softly limited');
    await saveAndWait(page);
    await expect(page.locator('#out-info')).toContainText('limiter on');
    const limited = await dbOf(page.locator('#out-peak'));
    expect(limited).toBeLessThanOrEqual(-0.5);
    expect(limited).toBeGreaterThan(-1.5);
  });

  test('Normalize to a peak of −1 dB makes the output peak close to −1 dB', async ({ page }) => {
    await load(page);
    await page.click('#tab-normalize');
    await expect(page.locator('#panel-normalize')).toBeVisible();
    await expect(page.locator('#peak-target')).toHaveValue('-1');
    await expect(page.locator('#norm-gain')).toHaveText(/^\+2[23]\.\d dB$/);
    await saveAndWait(page); // MP3 by default: the peak is measured on what goes into the encoder
    const outPeak = await dbOf(page.locator('#out-peak'));
    expect(Math.abs(outPeak - -1)).toBeLessThan(0.1);
    await expect(page.locator('#out-peak')).toHaveText('−1.0 dBFS');
  });

  test('Normalize to an RMS target sets the average loudness', async ({ page }) => {
    await load(page);
    await page.click('#tab-normalize');
    await page.check('#norm-rms');
    await page.fill('#rms-target', '-20');
    await page.check('#limit');
    await page.selectOption('#format', 'wav');
    await saveAndWait(page);
    const outRms = await dbOf(page.locator('#out-rms'));
    expect(Math.abs(outRms - -20)).toBeLessThan(1.5); // the limiter may shave a little off the peaks
    expect(await dbOf(page.locator('#out-peak'))).toBeLessThanOrEqual(-0.5);
  });

  test('Download saves an MP3 with the louder suffix', async ({ page }) => {
    await load(page);
    await saveAndWait(page);
    await expect(page.locator('#download')).toHaveText('Download quiet-sample-louder.mp3');
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('quiet-sample-louder.mp3');
    const bytes = fs.readFileSync(await download.path());
    expect(bytes.length).toBeGreaterThan(20_000); // 3 s at 160 kbps (the MPEG-2 maximum for 22.05 kHz)
    expect(bytes[0]).toBe(0xff);
    expect(bytes[1] & 0xe0).toBe(0xe0);
    await expect(page.locator('#out-size')).toHaveText(/\d+(\.\d)? KB/);
  });

  test('Download saves a WAV with a custom suffix, keeping the sample rate, channels and Unicode name', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', {
      name: 'café mémo ☕.wav',
      mimeType: 'audio/wav',
      buffer: fs.readFileSync(fixture('quiet-sample.wav')),
    });
    await expect(page.locator('#editor')).toBeVisible();
    await page.selectOption('#format', 'wav');
    await page.fill('#suffix', 'boosted');
    await saveAndWait(page);
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('café mémo ☕-boosted.wav');
    const bytes = fs.readFileSync(await download.path());
    expect(bytes.toString('ascii', 0, 4)).toBe('RIFF');
    expect(bytes.toString('ascii', 8, 12)).toBe('WAVE');
    expect(bytes.readUInt16LE(22)).toBe(2);        // stereo kept
    expect(bytes.readUInt32LE(24)).toBe(22050);    // sample rate kept
    expect(bytes.length).toBe(fs.statSync(fixture('quiet-sample.wav')).size);
  });

  test('a non-audio file shows an error message', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', fixture('sample.pdf'));
    await expect(page.locator('#results .alert--error')).toContainText('not an audio file');
    await expect(page.locator('#editor')).toBeHidden();
  });

  test('a file that looks like audio but cannot be decoded shows an error', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', { name: 'broken.mp3', mimeType: 'audio/mpeg', buffer: Buffer.from('this is not really audio data '.repeat(20)) });
    await expect(page.locator('#results .alert--error')).toContainText('could not be read as audio');
  });

  test('mixed files: the non-audio file is rejected, the audio file still loads', async ({ page }) => {
    await page.goto('./');
    // Drop both files on the drop zone (the picker allows a single file).
    const handle = await page.evaluateHandle(async () => {
      const dt = new DataTransfer();
      dt.items.add(new File(['plain text, not audio'], 'notes.txt', { type: 'text/plain' }));
      return dt;
    });
    const wav = fs.readFileSync(fixture('quiet-sample.wav')).toString('base64');
    await page.evaluate(async ([dt, b64]) => {
      const bin = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
      dt.items.add(new File([bin], 'quiet-sample.wav', { type: 'audio/wav' }));
      document.getElementById('dropzone').dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
    }, [handle, wav]);
    await expect(page.locator('#results .alert--error')).toContainText('"notes.txt" is not an audio file');
    await expect(page.locator('#editor')).toBeVisible();
    await expect(page.locator('#file-name')).toHaveText('quiet-sample.wav');
  });

  test('a silent file shows Silent and disables the controls', async ({ page }) => {
    await load(page, 'silent.wav');
    await expect(page.locator('#stat-peak')).toHaveText('Silent');
    await expect(page.locator('#stat-rms')).toHaveText('Silent');
    await expect(page.locator('#save')).toBeDisabled();
    await expect(page.locator('#gain')).toBeDisabled();
  });

  test('keyboard: arrows change gain by 0.5 dB, Shift by 3 dB, Space toggles the preview', async ({ page }) => {
    await load(page);
    await page.focus('#gain');
    await page.keyboard.press('ArrowRight');
    await expect(page.locator('#gain-out')).toHaveText('+6.5 dB');
    await page.keyboard.press('Shift+ArrowRight');
    await expect(page.locator('#gain-out')).toHaveText('+9.5 dB');
    await page.keyboard.press('ArrowLeft');
    await expect(page.locator('#gain-out')).toHaveText('+9.0 dB');
    await page.locator('#gain').blur();
    await page.locator('#file-name').click();
    await page.keyboard.press('Shift+ArrowLeft');
    await expect(page.locator('#gain-out')).toHaveText('+6.0 dB');
    await page.keyboard.press(' ');
    await expect(page.locator('#play')).toHaveAttribute('aria-pressed', 'true');
    await page.keyboard.press('b');
    await expect(page.locator('#ab-label')).toHaveText('Before');
    await page.keyboard.press(' ');
    await expect(page.locator('#play')).toHaveAttribute('aria-pressed', 'false');
  });

  test('the bundled sample button loads the Quiet Voice Memo', async ({ page }) => {
    await page.goto('./');
    await page.click('#try-sample');
    await expect(page.locator('#file-name')).toHaveText('Quiet Voice Memo.wav');
    await expect(page.locator('#stat-duration')).toHaveText('0:08.0');
    await expect(page.locator('#stat-peak')).toHaveText(/^−2[34]\.\d dBFS$/);
  });

  test('works at 390px wide: loads, saves and nothing overflows', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await load(page);
    await page.locator('#gain').fill('30');
    await saveAndWait(page);
    await expect(page.locator('#download')).toBeInViewport();
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    for (const sel of ['#save', '#wave', '#stat-rms', '#download', '#suffix']) {
      const box = await page.locator(sel).boundingBox();
      expect(box.x, sel).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width, sel).toBeLessThanOrEqual(391);
    }
  });

  test('window.__demo shows a finished result', async ({ page }) => {
    await page.goto('./');
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#file-name')).toHaveText('Quiet Voice Memo.wav');
    await expect(page.locator('#download')).toBeVisible();
  });
});
